#' Compare Matching and Weighting Estimators
#'
#' 
#' @param data .
#' @param outcome .
#' @param treat .
#' @param covs .
#' @param estimand .
#' @param link .
#' @param doNaive .
#' @param doRa .
#' @param doIpw .
#' @param doAipw .
#' @param doIpwra .
#' @param doNn .
#' @param doEbal .
#' @param k .
#' @param biasadj .
#' @param moments .
#' @param level .
#' @param plot .
#' @param showHelp .
#' @param showGuide .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$guide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$helpText} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$notes} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$est} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$forest} \tab \tab \tab \tab \tab an image \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$est$asDF}
#'
#' \code{as.data.frame(results$est)}
#'
#' @export
matchcmp <- function(
    data,
    outcome,
    treat,
    covs,
    estimand = "all",
    link = "logit",
    doNaive = TRUE,
    doRa = TRUE,
    doIpw = TRUE,
    doAipw = TRUE,
    doIpwra = TRUE,
    doNn = TRUE,
    doEbal = TRUE,
    k = 1,
    biasadj = TRUE,
    moments = "m1",
    level = 95,
    plot = TRUE,
    showHelp = FALSE,
    showGuide = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("matchcmp requires jmvcore to be installed (restart may be required)")

    if ( ! missing(outcome)) outcome <- jmvcore::resolveQuo(jmvcore::enquo(outcome))
    if ( ! missing(treat)) treat <- jmvcore::resolveQuo(jmvcore::enquo(treat))
    if ( ! missing(covs)) covs <- jmvcore::resolveQuo(jmvcore::enquo(covs))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(outcome), outcome, NULL),
            `if`( ! missing(treat), treat, NULL),
            `if`( ! missing(covs), covs, NULL))


    options <- matchcmpOptions$new(
        outcome = outcome,
        treat = treat,
        covs = covs,
        estimand = estimand,
        link = link,
        doNaive = doNaive,
        doRa = doRa,
        doIpw = doIpw,
        doAipw = doAipw,
        doIpwra = doIpwra,
        doNn = doNn,
        doEbal = doEbal,
        k = k,
        biasadj = biasadj,
        moments = moments,
        level = level,
        plot = plot,
        showHelp = showHelp,
        showGuide = showGuide)

    analysis <- matchcmpClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

